type Step = { kind: 'final'; answer: string }
       | { kind: 'tool';    tool: string; args: unknown };

async function agentLoop(state, llm, tools, maxSteps = 8) {
  for (let i = 0; i < maxSteps; i++) {
    const step: Step = await llm.decide(state);   // perceive + decide
    if (step.kind === 'final') return step.answer; // end
    const out = await tools[step.tool].run(step.args); // act
    state = state.observe(step, out);              // observe
  }
  throw new Error('loop budget exhausted');
}

